INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('fe3b4bc0-1fa6-49cf-ae6f-c2731d177e2e', '074a692b-919e-4499-944a-e6866e7475cc', 2, 'Day 15', 'Gumboro (IBD) vaccine.', NULL);
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('931bde8f-d090-4173-8aec-e35f2f4f2303', '074a692b-919e-4499-944a-e6866e7475cc', 3, 'Week 6 (Day 42)', 'Newcastle vaccine', 'repeat.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('220d9cbc-dfcb-4293-8c90-cac9f3c2758c', '074a692b-919e-4499-944a-e6866e7475cc', 4, 'Week 8-9', 'Fowl typhoid + Fowl pox vaccines.', NULL);
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('692007d8-c2a0-4df7-a884-511d1bc4ac3f', '074a692b-919e-4499-944a-e6866e7475cc', 5, 'Week 11', 'Coryza vaccine.', NULL);
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('972c89d6-59be-4663-8181-0f975e893e80', '074a692b-919e-4499-944a-e6866e7475cc', 6, 'Week 12', 'Move from brooder to cage.', '5,000 sold as POL pullets, 5,000 retained for Houses A & B replacement (2,500 each).');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('da16bd97-d7e7-4c51-b2a3-7ba7a431811a', '074a692b-919e-4499-944a-e6866e7475cc', 7, 'Week 14', 'Egg drop syndrome vaccine.', NULL);
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('1e599f76-6384-4ba1-a123-3ee97fabc062', '074a692b-919e-4499-944a-e6866e7475cc', 8, 'Monthly Days 1-3', 'Vitamins', 'administered to manage stress.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('53ce11ca-b9a4-4365-9620-2e9e8fcc36e8', '074a692b-919e-4499-944a-e6866e7475cc', 9, 'Days 15-17', 'Vitamins', 'mid-month dose.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('ff49ba0a-1caf-4ad4-aaaf-1853ec4ea04d', '074a692b-919e-4499-944a-e6866e7475cc', 10, 'Every 3 months', 'Deworming.', NULL);
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('40effaba-95b9-4b82-ad8b-9aa78fcc78ef', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 0, 'At birth', 'Weigh the calf', 'immediately after birth and record.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('022dd31d-af17-4c0d-9990-680bb284e68c', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 1, 'Within 4h', 'Bottle-feed mother''s colostrum.', NULL);
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('d1d0fda9-0f39-468f-9d80-b7978ddaad4e', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 2, 'Day 3', 'Introduce dry matter', 'hay and calf pellets.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('13f2efa9-a2ef-4c3d-81fa-2190c19864b9', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 3, 'Day 1-150', '6 L milk daily', '2 L morning, 2 L afternoon, 2 L evening, until 5 months.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('8bfe9966-9150-451a-9328-719099f77441', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 4, '2 months', 'First deworming.', 'Then monthly until 6 months.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('8c52e051-bf4e-4ce3-83d8-616fe04963aa', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 5, '3 months', 'Wean', 'when weight has doubled. Switch to dairy meal + dry matter + small ratio of napier. First vaccines: FMD, Lumpy Skin, Anthrax.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('1efe965f-7ce4-4eb0-a4f0-39a52f219d05', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 6, '6 months+', 'Deworming every 3 months', 'no longer "calf".');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('0ee5bcc9-7fcc-402e-91af-b8205a74b77e', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 7, 'Monthly', 'Vitamins.', NULL);
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('d52240b8-554a-47ce-9d75-7ab39ab17740', '6b8ef3f6-929c-4d13-a79a-0512ddcdb63d', 8, '14-15 months', 'Ready to serve', 'when on heat cycle.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('c5b49cb7-b918-4d2b-a643-5460249bc1d7', 'a90af7f5-4f89-4484-bd63-24b4bb3b5915', 0, 'Gestation', '3 weeks 3 days', 'gestation period (≈ 24 days).');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('8cc2a325-ec4f-456a-a5e1-be5031fb7cc4', 'a90af7f5-4f89-4484-bd63-24b4bb3b5915', 1, 'At farrowing', 'Suckle immediately.', 'Use sawdust as bedding.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('debb2e24-bb04-4e11-8753-a26242e93206', 'a90af7f5-4f89-4484-bd63-24b4bb3b5915', 2, 'Day 3', 'Administer iron, do tooth clipping', 'and docking.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('efef7768-3ce2-458c-89fd-d0447788e725', 'a90af7f5-4f89-4484-bd63-24b4bb3b5915', 3, 'Day 21', 'Iron (2nd dose), castrate males.', NULL);
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('2f0a8cc1-f65a-4a0c-93a6-3c48e5900526', 'a90af7f5-4f89-4484-bd63-24b4bb3b5915', 4, '2 months', 'Wean from sow.', 'No vaccines needed (natural insemination). Introduce growers feed.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('4c01b043-83be-4b7d-a8d1-87966c6ba7dd', 'a90af7f5-4f89-4484-bd63-24b4bb3b5915', 5, '4 months', 'Add protein', 'to help with fattening.');
INSERT INTO public."VetProtocolStep" (id, "templateId", "order", "dayLabel", procedure, notes) VALUES ('f4f65d2a-d272-4db9-b9ed-4ed4e0e6d205', 'a90af7f5-4f89-4484-bd63-24b4bb3b5915', 6, '6 months', 'Ready for market.', NULL);
